WITH valid AS (SELECT id, started_at, SUBSTRING(browser, 1, 4) AS browser_prefix, COALESCE(country, 'DIRECT') AS country_filled FROM sessions WHERE started_at > TIMESTAMP '2023-06-07 03:00:00' AND country NOT IN ('SG', 'US', 'TH')) SELECT DATE_TRUNC('WEEK', started_at) AS week_start, MIN(started_at) AS started_at, COUNT(*) AS event_count FROM valid GROUP BY DATE_TRUNC('WEEK', started_at);
